import{t as e}from"./link-C2W5MJHH.js";import{t}from"./jsx-runtime-NZYk81nU.js";import{a as n}from"./dist-pc87doUg.js";import{n as r}from"./PageHeader-towaNx_2.js";import{t as i}from"./button-DC4NoJ_F.js";var a=n(`arrow-left`,[[`path`,{d:`m12 19-7-7 7-7`,key:`1l729n`}],[`path`,{d:`M19 12H5`,key:`x3x0zl`}]]),o=JSON.parse(`[{"type":"paragraph","text":"For more than 50 years, NASA’s Human Research Program (HRP) has studied what happens to the human body in space and uses what it learns to design procedures, devices, and strategies that keep astronauts safe and healthy throughout their missions. The research also guides spacecraft and spacesuit design, medical standards, physical fitness programs, and training in physiological and psychological adaptation, sensorimotor skills, and nutritional health.","links":[{"text":"Human Research Program","url":"https://www.nasa.gov/hrp/"}]},{"type":"paragraph","text":"Understanding the effects of spaceflight is essential as astronauts move from the International Space Station in low-Earth orbit to destinations on and around the Moon, and beyond. Through the Artemis program, NASA will land the first woman and next man on the Moon, exploring more of the lunar surface than ever before while gathering new data and keeping astronauts healthy and safe.","links":[{"text":"International Space Station","url":"https://www.nasa.gov/international-space-station/"},{"text":"Artemis program","url":"https://www.nasa.gov/humans-in-space/step-3-artemis-moon-missions-as-an-astronaut-testbed-for-mars/"}]},{"type":"paragraph","text":"NASA is particularly interested in how the body reacts to long-duration spaceflight as it plans extended missions to the Moon and Mars. Scott Kelly and Christina Koch were the first American astronauts to spend nearly one year in space aboard the station, twice the previous average; they and seven other astronauts have spent more than 200 days in space during a single spaceflight. Scott also took part in the Twins Study, conducting biomedical studies in orbit while his identical twin brother, retired astronaut Mark Kelly, stayed on Earth as a control subject. The data they provided will be used by researchers for decades, and NASA is planning more dedicated extended-duration research on the station.","links":[{"text":"Scott Kelly","url":"https://www.nasa.gov/missions/station/looking-back-at-the-yearinspace/"},{"text":"more than 200 days in space during a single spaceflight","url":"https://www.nasa.gov/international-space-station/space-station-astronaut-record-holders/"},{"text":"Twins Study","url":"https://www.nasa.gov/humans-in-space/twins-study/"}]},{"type":"paragraph","text":"The risks are not the same for astronauts who spend six months on the station and those who may be away for years on a Mars mission. NASA groups the hazards of Mars missions into five categories, summarized by the acronym “RIDGE”: Space Radiation, Isolation and Confinement, Distance from Earth, Gravity fields, and Hostile/Closed Environments.","links":[]},{"type":"heading","text":"Space Radiation","links":[]},{"type":"paragraph","text":"On Earth, the planet’s magnetic field and atmosphere shield us from most of the space radiation environment, although everyone still receives low daily doses, from the food we eat to the air we breathe. In space, astronauts are exposed to higher and different radiation from three major sources: particles trapped in Earth’s magnetic field, solar energetic particles from the Sun, and galactic cosmic rays. Some of these particles, especially galactic cosmic rays, are difficult to shield against.","links":[{"text":"space radiation","url":"https://www.nasa.gov/hrp/radiation/"}]},{"type":"paragraph","text":"Increased radiation exposure can have both short- and long-term health consequences, depending on the total dose and the time frame over which it is received. On Earth, radiation has been linked to a higher risk of cancer and degenerative diseases, such as heart disease and cataracts. Animal and cellular research indicates that the type of radiation in space has a larger impact on health than the radiation experienced on Earth, so astronauts will face both more exposure and potentially greater risk, mainly from long-term effects.","links":[{"text":"cancer","url":"https://humanresearchroadmap.nasa.gov/evidence/reports/Cancer.pdf?rnd=0.592505168445644"},{"text":"degenerative diseases","url":"https://humanresearchroadmap.nasa.gov/evidence/reports/Degen.pdf?rnd=0.883156046216914"}]},{"type":"image","src":"/__l5e/assets-v1/095a1ee6-bdca-4b1a-8a0b-373b8d696b29/human-research-image1.png","caption":"ESA astronaut Samantha Cristoforetti replaces centrifuge components in the Columbus module’s BioLab, which studies the effects of space and radiation on micro-organisms. Credit: NASA"},{"type":"paragraph","text":"The Key: The current strategy to reduce radiation risk is shielding, radiation monitoring, and specific operational procedures. Because Moon and Mars missions will be much longer than typical six-month station stays, total exposure and associated health risks may increase. NASA is developing new detectors to monitor and characterize the radiation environment, and is using available vehicle stowage and materials to reduce exposure. Research at ground-based research facilities analyzes the biological effects of simulated cosmic rays, helps ensure doses are measured accurately, and supports the development of advanced shielding materials, while studies of radiation-exposed human cohorts estimate health risks for astronauts.","links":[{"text":"current strategy","url":"https://srag.jsc.nasa.gov/SpaceRadiation/How/How.cfm"},{"text":"monitor","url":"https://www.nasa.gov/mission/station/research-explorer/investigation/?"},{"text":"vehicle stowage","url":"https://www.nasa.gov/missions/artemis/orion/scientists-and-engineers-evaluate-orion-radiation-protection-plan/"},{"text":"ground-based research facilities","url":"https://www.bnl.gov/nsrl/about.php"}]},{"type":"heading","text":"Isolation and Confinement","links":[]},{"type":"paragraph","text":"Station crews are carefully chosen, trained, and supported to work effectively as a team during six- to 12-month missions. Moon and Mars crews will need even more careful assessment and preparation, since they will travel farther and longer in an isolated, confined environment with only a few other people. Crews will likely be international and multi-cultural, making cross-cultural sensitivity and team dynamics paramount to mission success.","links":[]},{"type":"paragraph","text":"Quality sleep is also important, because factors such as different dark and light cycles, a small and noisy habitat, the stress of prolonged isolation, and a 37-minute-longer day on Mars may alter astronauts’ circadian rhythm. Crews must also be prepared for fatigue, heavy workloads, and boredom during a multi-year round trip. Communication and understanding among crew members are vital, and morale and motivation may change as a mission unfolds because of reduced stimulation, longing for loved ones, or being unable to help with family emergencies back on Earth.","links":[{"text":"circadian rhythm","url":"https://humanresearchroadmap.nasa.gov/Evidence/reports/BMed.pdf"}]},{"type":"paragraph","text":"Research using spaceflight analogs on Earth shows that both the duration and type of confinement matter: the more restricted the space and the less contact with people outside it, the more likely humans are to develop behavioral or cognitive conditions or psychiatric disorders.","links":[{"text":"spaceflight analogs","url":"https://www.nasa.gov/humans-in-space/step-1-earth-analogs-help-advance-missions-to-moon-mars/"}]},{"type":"image","src":"/__l5e/assets-v1/7b39ff1a-671c-409d-9505-8dc67275627d/human-research-image2.png","caption":"NASA astronauts Jessica Watkins and Bob Hines work on a plant experiment aimed at producing crops to help sustain crews on farther missions. Credit: NASA"},{"type":"paragraph","text":"The Key: NASA has studied people in isolated and confined environments for years and has developed methods and technologies to counteract problems. Devices such as actigraphy, which records movement and ambient light, help assess and improve sleep and alertness, and new LED lighting on the station helps align circadian rhythms. A 10-minute self-test of vigilance measures the effect of fatigue, and journals give astronauts a safe place to vent while helping researchers study behavioral issues. Virtual reality may simulate relaxing environments, meaningful activities such as learning a language or medical skills could boost morale, and a space garden could offer behavioral benefits along with fresh food. Earth-based analogs are also revealing how much privacy and living space crews need, and studies of individual and team attributes are helping NASA form the best crew.","links":[{"text":"space garden","url":"https://www.nasa.gov/mission/station/research-explorer/investigation/?"},{"text":"crew","url":"https://humanresearchroadmap.nasa.gov/Evidence/reports/Team.pdf"}]},{"type":"heading","text":"Distance from Earth","links":[]},{"type":"paragraph","text":"The space station orbits 240 miles above Earth, the Moon is 1,000 times farther, and Mars is on average 140 million miles away. With a communication delay of up to 20 minutes one-way, Mars crews must be able to solve problems and find solutions as a team without help from mission control.","links":[{"text":"140 million miles","url":"https://sservi.nasa.gov/articles/how-far-is-it-to-mars/"},{"text":"20 minutes","url":"https://mars.nasa.gov/mer/mission/timeline/surfaceops/navigation/"}]},{"type":"paragraph","text":"Distance also limits supplies. Unlike station crews, who regularly receive cargo flights, astronauts traveling to Mars will have to bring all the food, equipment, and medical supplies they need for a multi-year trip, with no grocery store or pharmacy along the way.","links":[]},{"type":"image","src":"/__l5e/assets-v1/c7fa42a5-bfa7-4ae4-ba6c-aebd40b0edf9/human-research-image3.png"},{"type":"paragraph","text":"The Key: NASA is using station experience to learn which medical events occur in space and which skills, procedures, equipment, and supplies will be needed on future Moon and Mars missions. Astronauts already receive medical training before and during missions, including how to produce intravenous solution from purified water, and crew members perform ultrasound scans on each other and are ready to run laboratory tests to guide diagnosis and treatment. NASA is developing a medical data architecture for clinical decision support tools that could use artificial intelligence and machine learning, and is exploring virtual assistants to help crews respond quickly to anomalies. The agency is also improving food formulation, processing, packaging, and preservation, along with space-resilient medications and packaging, so nutrients and pharmaceuticals remain stable for years.","links":[{"text":"ultrasound scans","url":"https://www.nasa.gov/mission/station/research-explorer/investigation/?"},{"text":"clinical decision support tools","url":"https://ntrs.nasa.gov/archive/nasa/casi.ntrs.nasa.gov/20200000567.pdf"},{"text":"food formulation","url":"https://humanresearchroadmap.nasa.gov/Evidence/reports/AFT.pdf"}]},{"type":"heading","text":"Gravity Fields","links":[]},{"type":"paragraph","text":"A Mars mission involves three gravity fields: weightlessness during the six-month trip, roughly one-third of Earth’s gravity on Mars, and readaptation to Earth’s gravity on return. Each transition affects spatial orientation, head-eye and hand-eye coordination, balance, and locomotion, and some crew members experience space motion sickness. After moving from weightlessness to gravity, astronauts may also develop orthostatic intolerance, an inability to maintain blood pressure when standing that can cause lightheadedness and fainting.","links":[]},{"type":"paragraph","text":"Without gravity’s load, weight-bearing bones lose on average 1% to 1.5% of mineral density per month; the loss may not be fully corrected after return, though fracture risk is not higher. Muscle mass also declines faster than on Earth without the proper diet and exercise. Body fluids shift toward the head, which may put pressure on the eyes and cause vision problems, and dehydration and calcium loss from bones can raise the risk of kidney stones.","links":[{"text":"1% to 1.5%","url":"https://humanresearchroadmap.nasa.gov/Evidence/reports/Fracture.pdf"}]},{"type":"image","src":"/__l5e/assets-v1/ad73acb0-cafd-4125-b78a-3198b175d109/human-research-image4.png","caption":"NASA astronaut Bob Hines works out on a resistive exercise device aboard the space station. Credit: NASA"},{"type":"paragraph","text":"The Key: NASA is developing protective measures by studying how the body changes in weightlessness and after returning to gravity. Functional task testing and Fine motor skill testing detect changes in balance and dexterity, while fluid distribution is monitored for links to vision changes and thigh compression cuffs or a lower-body negative pressure device could counteract fluid shifts. Back pain is monitored with spinal ultrasounds, muscle and bone are assessed with MRI and high-resolution imaging, and periodic fitness self-evaluations track heart function. Potassium citrate may reduce kidney stone risk, bisphosphonates have prevented bone loss, and urine collection helps researchers adjust diet, exercise, and water intake to prevent kidney stones. Aerobic and resistive exercise keeps the heart healthy and bones and muscles strong, may improve balance and coordination, and could be supported by software-generated workout partners, while a bed rest study tested whether centrifuge artificial gravity can counter the effects of weightlessness.","links":[{"text":"Functional task testing","url":"https://www.nasa.gov/mission/station/research-explorer/investigation/?"},{"text":"Fine motor skill","url":"https://www.nasa.gov/mission/station/research-explorer/investigation/?"},{"text":"vision","url":"https://www.nasa.gov/mission/station/research-explorer/investigation/?"},{"text":"spinal ultrasounds","url":"https://www.nasa.gov/mission/station/research-explorer/investigation/?"},{"text":"periodic fitness self-evaluations","url":"https://www.nasa.gov/mission/station/research-explorer/investigation/?"},{"text":"kidney stone","url":"https://humanresearchroadmap.nasa.gov/Evidence/reports/Renal.pdf"},{"text":"bones and muscles strong","url":"https://www.nasa.gov/mission/station/research-explorer/investigation/?"},{"text":"balance and coordination","url":"https://www.nasa.gov/mission/station/research-explorer/investigation/?"},{"text":"centrifuge artificial gravity","url":"https://www.nasa.gov/humans-in-space/one-small-step-without-ever-leaving-bed/"}]},{"type":"heading","text":"Hostile/Closed Environments","links":[]},{"type":"image","src":"/__l5e/assets-v1/495a4298-aae8-4ea2-b1c5-957ba34be6f5/human-research-image5.png","caption":"Expedition 67 flight engineers squeeze inside Boeing’s CST-100 Starliner spacecraft, which carries astronauts to the space station. Credit: NASA"},{"type":"paragraph","text":"The ecosystem inside a spacecraft plays a big role in daily life. Microbes can change in space, and micro-organisms that live on the human body pass more easily between people in closed habitats such as the station. Stress hormone levels rise and the immune system is altered, which could increase susceptibility to allergies or other illnesses, although crews do not tend to get sick after returning to Earth and their acquired immunity remains intact. More research is needed on whether altered immunity could lead to autoimmune issues. Earth-based analogs cannot perfectly simulate spaceflight, but NASA-funded Antarctic studies offer some insight.","links":[]},{"type":"paragraph","text":"Living and working quarters must also be carefully designed: no one wants a habitat that is too hot, too cold, cramped, crowded, loud, or poorly lit, and designs must balance comfort with efficiency.","links":[]},{"type":"image","src":"/__l5e/assets-v1/707c2871-01d4-452d-8b90-0cd8a9257c19/human-research-image6.jpeg","caption":"NASA astronaut Scott Kelly gives himself a flu shot to help researchers study how spaceflight affects the immune system. Credit: NASA"},{"type":"paragraph","text":"The Key: NASA monitors the station’s air for contaminants such as formaldehyde, ammonia, and carbon monoxide, and thermal control systems and new LED lighting, similar to natural light on Earth, keep the environment comfortable. Blood and saliva samples reveal immune changes and reactivation of latent viruses, advanced molecular techniques evaluate microbial risks, and regular swabs of crew and station surfaces track the microbial population. Crews change air filters, clean surfaces, and treat water to prevent illness. Astronauts receive a flu shot and are quarantined before launch; during the Twins Study and One-Year Mission, Scott Kelly vaccinated himself in space, and the vaccine worked as well as on Earth, a good finding for longer missions.","links":[{"text":"thermal control systems","url":"https://www.nasa.gov/wp-content/uploads/2021/02/473486main_iss_atcs_overview.pdf?emrc=046ace"},{"text":"LED","url":"https://www.nasa.gov/mission/station/research-explorer/investigation/?"},{"text":"flu","url":"https://www.nasa.gov/mission/station/research-explorer/investigation/?"},{"text":"quarantined","url":"https://ntrs.nasa.gov/archive/nasa/casi.ntrs.nasa.gov/20130000048.pdf"}]},{"type":"paragraph","text":"NASA is acting on all of these risks, and results from laboratories, ground analogs, and station missions provide a stepping stone for longer missions. Upcoming Artemis missions will gather even more data, helping future Moon and Mars crews not just survive but thrive.","links":[{"text":"stepping stone","url":"https://www.nasa.gov/humans-in-space/nasas-human-research-program-three-steps-to-mars/"}]},{"type":"paragraph","text":"Click here for an infographic summarizing the risks of human spaceflight and the safeguards against them.","links":[{"text":"here","url":"https://www.nasa.gov/humans-in-space/human-body-in-space-infographic/"}]},{"type":"paragraph","text":"_______","links":[]},{"type":"paragraph","text":"NASA’s Human Research Program pursues the best methods and technologies for safe, productive human space travel through laboratory research, ground-based analogs, and the International Space Station. This work drives HRP’s quest to keep astronauts healthy and mission-ready as travel expands to the Moon, Mars, and beyond.","links":[{"text":"Human Research Program","url":"https://www.nasa.gov/hrp/"},{"text":"quest","url":"https://www.nasa.gov/humans-in-space/nasas-human-research-program-three-steps-to-mars/"}]}]`),s=t();function c(e){let t=e.split(`/`).pop();return t?`/offline-assets/${t}`:e}function l(e,t=[]){let n=[],r=0;for(;r<e.length;){let i=t.filter(e=>e.text&&/^https:\/\//.test(e.url)).map(t=>({...t,start:e.indexOf(t.text,r)})).filter(e=>e.start>=r).sort((e,t)=>e.start-t.start)[0];if(!i){n.push(e.slice(r));break}n.push(e.slice(r,i.start)),n.push((0,s.jsx)(`a`,{href:i.url,target:`_blank`,rel:`noopener noreferrer`,className:`text-primary underline underline-offset-4 hover:text-primary-glow`,children:i.text},`${i.start}-${i.url}`)),r=i.start+i.text.length}return n}function u(){return(0,s.jsxs)(`div`,{className:`mx-auto max-w-4xl space-y-6`,children:[(0,s.jsx)(i,{asChild:!0,variant:`ghost`,className:`px-0`,children:(0,s.jsxs)(e,{to:`/learn`,children:[(0,s.jsx)(a,{}),` Education Centre`]})}),(0,s.jsx)(r,{kicker:`Human spaceflight · Research`,title:`The Human Research`}),(0,s.jsx)(`p`,{className:`border-l-2 border-primary pl-4 text-sm leading-relaxed text-muted-foreground`,children:`From your supplied document, “The Human Research”. Photographs credited to NASA. Historical statements are reproduced as supplied; this is educational material, not personal medical advice.`}),(0,s.jsx)(`article`,{className:`space-y-6 pb-8`,children:o.map((e,t)=>{if(e.type===`heading`)return(0,s.jsx)(`h2`,{className:`border-t border-border pt-8 text-2xl font-semibold text-foreground`,children:e.text},t);if(e.type===`image`)return(0,s.jsxs)(`figure`,{className:`my-8`,children:[(0,s.jsx)(`img`,{src:c(e.src),alt:e.caption?.replace(/\s*Credit:.*$/,``)??`NASA human spaceflight research`,loading:`lazy`,className:`mx-auto h-auto max-h-[620px] w-full rounded-lg object-contain`}),e.caption&&(0,s.jsx)(`figcaption`,{className:`mt-3 text-sm leading-relaxed text-muted-foreground`,children:e.caption})]},t);let n=e.text??``,r=n.startsWith(`The Key:`);return(0,s.jsxs)(`p`,{className:r?`border-l-2 border-teal pl-4 text-base leading-8 text-foreground`:`text-base leading-8 text-foreground`,children:[r&&(0,s.jsx)(`strong`,{className:`text-teal`,children:`The Key: `}),l(r?n.slice(9).trimStart():n,e.links)]},t)})})]})}export{u as component};